openapi: 3.1.0

info:
  title: Sport Analytics API
  version: 1.0.0
  description: |
    Version-controlled contract for the handwritten Sport Analytics backend API.

    The supported API major version is `v1`; every documented path is served
    beneath `/api/v1`. URI paths are the only version-selection mechanism.
    Unsupported major-version paths return `404` with
    `UNSUPPORTED_API_VERSION`; request headers do not negotiate another API version.

    Operations marked with `x-implementation-status: planned` document agreed
    contracts that are not yet implemented. Implemented operations describe
    current backend behaviour.
x-ai-declaration: >-
  The preceding OpenAPI document was planned, generated, reviewed and edited
  with the assistance of ChatGPT-Web[GPT-5.6 Sol] and Codex[GPT-5].
x-api-versioning:
  versioning: uri-major
  supportedVersions: [v1]
  basePath: /api/v1
  responseHeader: API-Version
  unsupportedVersion:
    status: 404
    code: UNSUPPORTED_API_VERSION
servers:
  - url: statsthegame-api-dev-eecff5bbfjbyhbb2.southafricanorth-01.azurewebsites.net
    description: Development API

security: []

tags:
  - name: Health
    description: Service health and availability.

  - name: Authentication and Profile
    description: Managed-authentication identity and profile-related operations.

  - name: Public Read
    description: Anonymous sport-reference, fixture, accepted-event and statistic reads.

  - name: Weather
    description: >-
      Contextual weather lookup for a location and date, backed by the
      Open-Meteo external API. See ADR-008 for the integration decision.

  - name: Submissions
    description: Approved-submitter event-submission operations.

  - name: Submitter Access
    description: Authenticated submitter-access request operations.

  - name: Administration
    description: Administrator-only application-account and submitter-scope operations.

paths:
  /api/v1/health:
    get:
      tags:
        - Health
      summary: Check API health
      operationId: getHealth
      x-implementation-status: implemented
      security: []
      responses:
        '200':
          description: API is running.
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/HealthResponse'
              example:
                status: ok
                service: sport-analytics-api
                timestamp: '2026-08-09T14:00:00.000Z'

  /api/v1/auth/me:
    get:
      tags:
        - Authentication and Profile
      summary: Return the current application user profile
      description: |
        Verifies the bearer token through Supabase Auth, creates or synchronizes
        the provider-neutral application account, and returns server-owned role,
        submitter-approval and competition-scope state.

        Authentication never grants or changes approval, role or scope.
      operationId: getCurrentUserProfile
      x-implementation-status: implemented
      security:
        - bearerAuth: []
      responses:
        '200':
          description: Current synchronized application user profile.
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/CurrentUserProfileResponse'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          $ref: '#/components/responses/Forbidden'

  /api/v1/account:
    delete:
      tags:
        - Authentication and Profile
      summary: Permanently delete the authenticated account
      description: |
        Requires an exact `DELETE` confirmation and a Supabase sign-in no more
        than 15 minutes old. With server-only Supabase administration configured,
        the backend immediately disables the local account, removes its
        authorisation grants, hard-deletes its Supabase Auth user, and tombstones
        local identity fields.

        Cricket submissions, fixtures, deliveries, statistics and their stable
        provenance link remain available without the former display name or
        reusable authentication subject. If the server-only key is absent, the
        operation fails before changing local state.
      operationId: deleteCurrentAccount
      x-implementation-status: implemented
      security:
        - bearerAuth: []
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: '#/components/schemas/AccountDeletionRequest'
      responses:
        '200':
          description: Account identity deleted and local session may now be cleared.
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/AccountDeletionResponse'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          description: The identity was not authenticated recently enough.
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/ApiErrorResponse'
        '422':
          description: The exact deletion confirmation was not supplied.
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/ApiErrorResponse'
        '501':
          description: Server-only Supabase Auth administration is not configured.
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/ApiErrorResponse'
        '503':
          description: |
            Deletion could not be completed. The local account remains disabled
            and the operation can be retried safely.
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/ApiErrorResponse'

  /api/v1/submitter-access-requests:
    post:
      tags:
        - Submitter Access
      summary: Request submitter access
      description: |
        Creates a competition-scoped submitter-access request for the
        authenticated application account by validating and storing the
        requested competition while transitioning an eligible server-owned
        approval state to `pending`.

        Accounts already in `pending` or `approved` state cannot create another
        active request. A previously rejected account may request access again.
